import React, { useState, useEffect } from "react";
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Legend, Cell, CartesianGrid, PieChart, Pie } from "recharts";
import { ArrowTrendingUpIcon } from "@heroicons/react/24/solid";

const COLORS = ["#3b82f6", "#10b981", "#f59e42", "#f43f5e", "#6366f1", "#fbbf24", "#14b8a6"];

function getMonthsRemaining(deadline) {
  const now = new Date();
  const end = new Date(deadline);
  return Math.max(
    1,
    (end.getFullYear() - now.getFullYear()) * 12 + (end.getMonth() - now.getMonth())
  );
}

function getMonthlySavings(goal) {
  const months = getMonthsRemaining(goal.deadline);
  const amountLeft = Math.max(goal.amount - (goal.saved || 0), 0);
  return +(amountLeft / months).toFixed(2);
}

const Overview = ({ goals, income, currentSavings, plan }) => {
  const [chartData, setChartData] = useState([]);

  useEffect(() => {
    if (!goals || !plan) return;

    const newChartData = goals.map(goal => {
      const monthlyAllocation = plan.monthlyAllocations?.[goal.id] || 0;
      const totalAllocation = plan.totalAllocations?.[goal.id] || 0;
      const targetAmount = goal.targetAmount || 0;
      const remainingSavings = plan.amountLeft?.[goal.id] || targetAmount;

      return {
        name: goal.name,
        monthlyAllocation,
        totalAllocation,
        targetAmount,
        remainingSavings,
        color: goal.color || '#4ade80'
      };
    });

    // Add total row
    const totalRow = {
      name: 'Total',
      monthlyAllocation: plan.totalMonthlyNeeded || 0,
      totalAllocation: plan.totalSavingsNeeded || 0,
      targetAmount: goals.reduce((sum, goal) => sum + (goal.targetAmount || 0), 0),
      remainingSavings: plan.totalRemainingNeeded || 0,
      color: '#4ade80'
    };

    setChartData([...newChartData, totalRow]);
  }, [goals, plan]);

  // Calculate total target amount
  const totalTarget = goals.reduce((sum, goal) => sum + (goal.targetAmount || 0), 0);
  const totalSaved = plan?.totalSavingsNeeded || 0;
  const totalRemaining = plan?.totalRemainingNeeded || 0;
  const monthlyNeeded = plan?.totalMonthlyNeeded || 0;
  const shortfall = monthlyNeeded > (income?.monthlyDisposableIncome || 0) 
    ? monthlyNeeded - (income?.monthlyDisposableIncome || 0) 
    : 0;

  // Calculate pie chart data
  const pieChartData = goals.map(goal => ({
    name: goal.name,
    value: plan?.monthlyAllocations?.[goal.id] || 0,
    color: goal.color || '#4ade80'
  }));

  // Add total row to pie chart data
  const totalPieData = {
    name: 'Total',
    value: plan?.totalMonthlyNeeded || 0,
    color: '#4ade80'
  };
  pieChartData.push(totalPieData);

  // Calculate percentages for pie chart labels
  const totalMonthly = plan?.totalMonthlyNeeded || 0;
  const pieChartDataWithPercentages = pieChartData.map(item => ({
    ...item,
    percentage: totalMonthly > 0 ? ((item.value / totalMonthly) * 100).toFixed(1) : 0
  }));

  const RADIAN = Math.PI / 180;
  const renderCustomizedLabel = ({ cx, cy, midAngle, innerRadius, outerRadius, percent, index }) => {
    const radius = innerRadius + (outerRadius - innerRadius) * 0.5;
    const x = cx + radius * Math.cos(-midAngle * RADIAN);
    const y = cy + radius * Math.sin(-midAngle * RADIAN);

    return (
      <text
        x={x}
        y={y}
        fill="white"
        textAnchor={x > cx ? 'start' : 'end'}
        dominantBaseline="central"
        className="text-sm font-medium"
      >
        {`${(percent * 100).toFixed(0)}%`}
      </text>
    );
  };

  return (
    <div className="space-y-6">
